select 'rel' k, count(*) n, md5(coalesce(string_agg(x, E'\n' order by x),'')) h from (select n.nspname||'.'||c.relname||'|'||coalesce(r.rolname,'PUBLIC')||'|'||a.privilege_type x from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(c.relacl) a left join pg_roles r on r.oid=a.grantee where n.nspname in ('public','internal','saas')) s
union all select 'fn', count(*), md5(coalesce(string_agg(x, E'\n' order by x),'')) from (select n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')|'||coalesce(r.rolname,'PUBLIC')||'|'||a.privilege_type x from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(p.proacl) a left join pg_roles r on r.oid=a.grantee where n.nspname in ('public','internal','saas')) s
union all select 'nsp', count(*), md5(coalesce(string_agg(x, E'\n' order by x),'')) from (select n.nspname||'|'||coalesce(r.rolname,'PUBLIC')||'|'||a.privilege_type x from pg_namespace n cross join lateral aclexplode(n.nspacl) a left join pg_roles r on r.oid=a.grantee where n.nspname in ('public','internal','saas')) s;
